using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using ACI.Domain.Enums;
using ACI.Infrastructure.Persistence;
using FluentAssertions;
using Microsoft.Extensions.DependencyInjection;
using static ACI.WebApi.Tests.Helpers.Workspaces;

namespace ACI.WebApi.Tests;

/// <summary>
/// The MCP key is its own key: generated by an owner or manager, shown once, stored as a hash.
/// </summary>
public class McpKeyTests
{
    private static StringContent ToolsList() =>
        new("""{"jsonrpc":"2.0","id":1,"method":"tools/list"}""", Encoding.UTF8, "application/json");

    [Fact]
    public async Task AnOwnerGeneratesAKeyThatOpensMcpAndIsNotStored()
    {
        using var factory = new CustomWebApplicationFactory();
        var (owner, ownerId) = await SignInAsync(factory, "owner@example.ch");
        var org = await CreateAsync(factory, ownerId, "Club Nautique");

        var res = await owner.In(org).PostAsync($"/api/webhook/organizations/{org}/generate-mcp-key", null);
        res.IsSuccessStatusCode.Should().BeTrue(await res.Content.ReadAsStringAsync());
        using var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync());
        var key = doc.RootElement.GetProperty("apiKey").GetString()!;
        key.Should().StartWith("aci_mcp_");

        var mcp = factory.CreateClient();
        mcp.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
        mcp.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        (await mcp.PostAsync("/mcp", ToolsList())).StatusCode.Should().Be(HttpStatusCode.OK);

        var stored = await factory.Services.Read(db => db.Organizations.Single(o => o.Id == org));
        stored.McpApiKeyHash.Should().NotBeNullOrEmpty().And.NotContain(key);

        var info = await owner.In(org).GetStringAsync($"/api/webhook/organizations/{org}");
        info.Should().Contain("\"hasMcpApiKey\":true").And.NotContain(key);
    }

    [Fact]
    public async Task AMemberCannotGenerateOne()
    {
        using var factory = new CustomWebApplicationFactory();
        var (_, ownerId) = await SignInAsync(factory, "owner@example.ch");
        var org = await CreateAsync(factory, ownerId, "Club Nautique");
        var (member, memberId) = await SignInAsync(factory, "rep@example.ch");
        await AddMemberAsync(factory, org, memberId, OrgMemberRole.Member);

        var res = await member.In(org).PostAsync($"/api/webhook/organizations/{org}/generate-mcp-key", null);

        res.StatusCode.Should().Be(HttpStatusCode.Forbidden, await res.Content.ReadAsStringAsync());
    }
}
